import {t,text,language} from './i18n.js';
import {catalog,fieldMap,validWeeklyHours,backgroundSteps,visibleFields,buildPlan,possibleProfileCount,outputInventory} from './explorer-engine.js';
export const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHTML,T=(s,p)=>e(t(s,p)),X=v=>e(text(v));
export const sections=['overview','ai','careers','plan','sdg','catalog'];
export const sectionLabels={overview:'Overview',ai:'You & AI',careers:'Career directions',plan:'Learning plan',sdg:'SDG companions',catalog:'All outcomes & rules'};
export const button=(key,action,cls='button primary')=>`<button type="button" class="${cls}" data-action="${action}">${T(key)}</button>`;
export function answerLabel(p,key){
 if(key==='weeklyTime'&&p.omitLearningPreferences)return validWeeklyHours(p.exactWeeklyHours)?t('{hours} hours / week',{hours:p.exactWeeklyHours}):'—';
 if(key==='nationality')return p[key]==='undisclosed'?t('Prefer not to say'):countryName(p[key]);
 const f=fieldMap[key],v=p[key],values=Array.isArray(v)?v:[v];
 return values.filter(Boolean).map(id=>text(f.options.find(o=>o.id===id)?.label||id)).join(' · ');
}
function countryName(code){try{return new Intl.DisplayNames([language],{type:'region'}).of(code)||code;}catch{return code;}}
export function avatar(goal,size='small'){
 const n=goal.id-1,col=n%6,row=Math.floor(n/6);
 return `<span class="ex-avatar ex-avatar-${size}" role="img" aria-label="${X(goal.name)}" style="--sprite-x:${col*20}%;--sprite-y:${row*50}%"></span>`;
}
export function renderHeader(state){
 return `<header class="site-header"><div class="shell header-inner"><button type="button" class="brand" data-action="home" aria-label="${T('AI Career Navigator home')}"><span class="brand-mark"><i></i><i></i><i></i></span><span>AI Career<br><b>Navigator</b></span></button><div class="header-actions"><span class="ex-local-tag"><i></i>${T('OFFLINE EXPLORATION')}</span><label class="language-switch"><span class="sr-only">${T('Language')}</span><select id="language-select" aria-label="${T('Language')}">${[['en','English'],['zh-CN','简体中文'],['ms','Bahasa Melayu']].map(([id,name])=>`<option value="${id}" ${language===id?'selected':''}>${name}</option>`).join('')}</select></label>${button(state.report?'Edit your answers ↗':'Start assessment',state.report?'edit':'start','button small dark')}</div></div></header>`;
}
export function renderFooter(){return `<footer class="site-footer"><div class="shell footer-inner"><span>AI Career Navigator · Nexus</span><span>${T('Local rules · no online prediction')}</span></div></footer>`;}
export function renderHome(){
 const nova=catalog.goals.find(g=>g.id===9),luma=catalog.goals.find(g=>g.id===4);
 return `<main><section class="shell ex-hero"><div><span class="kicker">${T('Your curiosity. Your pace. Your next chapter.')}</span><h1>${T('A future worth exploring.')}</h1><p class="hero-lede">${T('Answer with choices. Explore career directions, build a learning plan and meet your SDG action companions.')}</p><div class="hero-buttons">${button('Start assessment','start')}${button('Explore a sample','sample','button secondary')}</div><p class="ex-privacy">${T('Your answers stay in this tab. Reports are assembled on your device from a reviewed catalog; no profile is sent to an AI service.')}</p><div class="ex-metrics"><span>${T('Four steps · mostly choices')}</span><span>${T('Same answers, same result')}</span></div></div><div class="ex-hero-art"><span class="ex-art-caption">${T('17 companions, one shared future.')}</span><div class="ex-hero-figures">${avatar(nova,'hero')}${avatar(luma,'hero')}</div><div class="ex-art-foot"><span><b>NOVA</b> / <b>LUMA</b></span><span>SDG 09 + 04</span></div></div></section><section class="proof-strip"><div class="shell proof-inner"><span>${T('24 career directions')}</span><span class="proof-divider"></span><span>${T('17 action companions')}</span><span class="proof-divider"></span><span>${T('Same answers, same result')}</span></div></section><section class="shell section ex-approach"><div class="section-heading"><div><span class="kicker">${T('THE APPROACH')}</span><h2>${T('From preferences to practical experiments.')}</h2></div><p>${T('Age and education adapt the next steps. They do not change which careers you can explore.')}</p></div><div class="ex-four-grid">${[['01','Choose your context','Education, interests, AI habits and a sustainable learning rhythm.'],['02','Understand the reasoning','Every direction shows the selected signals behind its ranking.'],['03','Try one small project','Compare two paths and check the result before a major decision.'],['04','Make a positive contribution','Connect a practical task to a global goal, without claiming measured impact.']].map(([n,h,p])=>`<article class="ex-mini"><span class="kicker">${n}</span><h3>${T(h)}</h3><p>${T(p)}</p></article>`).join('')}</div><div class="ex-secondary-actions">${button('Meet the 17 companions','gallery','button secondary')}${button('See the rules and all outcomes','catalog','text-button')}</div></section></main>`;
}
function renderQuestion(key,p,errors){
 if(key==='nationality')return ''; // Retain legacy profile compatibility without collecting nationality.
 if(key==='weeklyTime'&&p.omitLearningPreferences){
  const known=validWeeklyHours(p.exactWeeklyHours),value=known?p.exactWeeklyHours:5,error=errors.weeklyTime;
  return `<fieldset class="field choice-field"><legend id="label-weeklyTime">${X(fieldMap.weeklyTime.label)} *</legend><p class="field-help">${T('Drag the slider or enter exact hours. Each step is 30 minutes.')}</p><div class="weekly-hours-control"><input type="range" id="field-weeklyTime" name="exactWeeklyHours" data-exact-hours="range" min="0" max="60" step="0.5" value="${value}" aria-labelledby="label-weeklyTime" aria-invalid="${!!error}"><label for="weekly-hours-number" class="sr-only">${T('Exact weekly learning hours')}</label><input type="number" id="weekly-hours-number" data-exact-hours="number" min="0" max="60" step="0.5" value="${known?value:''}" inputmode="decimal" placeholder="—"><output id="weekly-hours-value" for="field-weeklyTime weekly-hours-number" aria-live="polite">${known?T('{hours} hours / week',{hours:value}):T('Choose your weekly learning time')}</output></div>${error?`<p class="field-error" id="error-weeklyTime">${T(error)}</p>`:''}</fieldset>`;
 }
 const f=fieldMap[key],v=p[key],values=Array.isArray(v)?v:[v],error=errors[key],aria=`aria-labelledby="label-${key}" ${error?`aria-describedby="error-${key}"`:''}`;
 const input=f.options.length>6&&!f.multi?`<select id="field-${key}" name="${key}" data-field="${key}" ${aria} aria-invalid="${!!error}"><option value="">${T('Select an option')}</option>${f.options.map(o=>`<option value="${o.id}" ${values.includes(o.id)?'selected':''}>${X(o.label)}</option>`).join('')}</select>`:`<div class="choice-grid ${f.options.length<4?'ex-compact-choices':''}" id="field-${key}" tabindex="-1" ${aria}>${f.options.map(o=>`<label class="choice ${values.includes(o.id)?'is-selected':''}"><input type="${f.multi?'checkbox':'radio'}" name="${key}" data-field="${key}" value="${o.id}" ${values.includes(o.id)?'checked':''} ${error?'aria-invalid="true"':''}><span>${X(o.label)}</span></label>`).join('')}</div>`;
 return `<fieldset class="field choice-field"><legend id="label-${key}">${X(f.label)}${f.optional?'':' *'}</legend><p class="field-help">${T(f.multi?'Choose all that apply.':'Choose one.')}${key==='gender'?' '+T('Not used to rank careers.'):''}</p>${input}${error?`<p class="field-error" id="error-${key}" role="alert">${T(error)}</p>`:''}</fieldset>`;
}
export function renderForm(state){
 const step=catalog.steps[state.step],steps=backgroundSteps(state.profile),position=steps.indexOf(state.step),percent=Math.round((position+1)/steps.length*100);
 return `<main class="form-page"><div class="shell"><div class="back-row">${button(state.step?'← Previous step':'← Back to home',state.step?'prev':'home','text-button')}</div><div class="form-shell"><aside class="form-side"><span class="kicker">${T('Your answers, your choice.')}</span><h1>${X(step.title)}</h1><p>${T('Choose what feels closest today. You can change it at any time.')}</p><ol class="ex-steps">${steps.map((i,n)=>{const s=catalog.steps[i];return `<li class="${i===state.step?'active':''}" ${i===state.step?'aria-current="step"':''}><span>0${n+1}</span>${X(s.title)}</li>`;}).join('')}</ol><div class="privacy-note"><span>✳</span><div><strong>${T('Your profile stays local; only your language choice is saved automatically.')}</strong><p>${T('Multi-select questions are marked. There is no correct personality or ideal background.')}</p></div></div></aside><div class="form-card"><div class="progress-top"><span>${T('Step {step} of {total}',{step:position+1,total:steps.length})}</span><span>${percent}%</span></div><div class="progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent}" aria-label="${T('Questionnaire overview')}"><div style="width:${percent}%"></div></div><h2>${X(step.title)}</h2><p class="form-intro">${T(state.step===0?'Age ranges do not overlap; subject fields appear only when relevant.':state.step===2?'Usage time and reliance describe habits, not competence or replacement risk.':'Your selected language changes the interface, not your answers or ranking.')}</p><form id="explorer-form" novalidate>${Object.keys(state.errors).length?`<p class="field-error" role="alert">${T('Complete the highlighted choices to continue.')}</p>`:''}${visibleFields(state.profile,state.step).map(k=>renderQuestion(k,state.profile,state.errors)).join('')}<div class="form-actions"><span>${T('Step {step} of {total}',{step:position+1,total:steps.length})}</span><button type="submit" class="button primary">${T(state.step===3?'View my exploration report':'Continue')} →</button></div></form></div></div></div></main>`;
}
function heading(kicker,title,body){return `<div class="report-head"><span class="kicker">${T(kicker)}</span><h1>${T(title)}</h1>${body?`<p>${T(body)}</p>`:''}</div>`;}
function advice(id){const a=catalog.advice[id];return `<article class="ex-advice"><h3>${X(a.title)}</h3><p>${X(a.body)}</p></article>`;}
function roleById(id){return catalog.careers.find(r=>r.id===id);}
function goalById(id){return catalog.goals.find(g=>g.id===id);}
function reasonList(rank,p){
 const r=rank.reasons,lines=[];
 if(r.interests.length)lines.push([t('Matching interests'),r.interests.map(v=>answerLabel({...p,interests:[v]},'interests')).join(' · ')]);
 if(r.major)lines.push([t('Subject connection'),answerLabel(p,'major')]);
 if(r.stream)lines.push([t('School stream connection'),answerLabel(p,'stream')]);
 if(r.mindsets.length)lines.push([t('Thinking preferences'),r.mindsets.map(v=>answerLabel({...p,mindsets:[v]},'mindsets')).join(' · ')]);
 if(r.aiPurposes.length)lines.push([t('AI-purpose overlap'),r.aiPurposes.map(v=>answerLabel({...p,aiPurposes:[v]},'aiPurposes')).join(' · ')]);
 return lines.length?`<ul class="ex-reasons">${lines.map(([a,b])=>`<li><b>${e(a)}</b><span>${e(b)}</span></li>`).join('')}</ul>`:`<p class="field-help">${T('Limited signals: compare this option with alternatives before choosing.')}</p>`;
}
function overview(report){
 const role=roleById(report.ranking[0].id),goal=goalById(report.goals[0].id),p=report.profile;
 return heading('YOUR EXPLORATION REPORT','Possibilities to test, at your pace.','This is a local exploration aid, not a validated aptitude test, hiring prediction or fixed personality type.')+`<div class="ex-overview-grid"><section class="ex-feature"><span class="kicker">${T('START HERE')}</span><h2>${X(role.title)}</h2><p>${X(role.project)}</p>${reasonList(report.ranking[0],p)}${button('Compare A and B','page:careers','button secondary')}</section><section class="ex-companion-preview" style="--goal-color:${goal.color}">${avatar(goal,'feature')}<span class="ex-persona-code">${e(report.preferenceCode)} · ${goal.code}</span><h3>${X(goal.name)}</h3><p>SDG ${goal.id} · ${X(goal.title)}</p>${button('View companion','page:sdg','text-button')}</section></div>${['child','teen'].includes(p.age)?`<p class="info-banner">${T('For younger learners, these are future exploration ideas, not immediate job recommendations.')}</p>`:''}<h2>${T('Your learning rhythm')}</h2><div class="ex-two-grid">${report.learning.filter(id=>!id.startsWith('style-')&&id!=='cross-border').slice(0,6).map(advice).join('')}</div><details class="ex-detail"><summary>${T('Questionnaire overview')}</summary><dl class="ex-answer-list">${catalog.steps.flatMap((_,i)=>visibleFields(p,i)).map(k=>`<div><dt>${k==='nationality'?T('Nationality (optional)'):X(fieldMap[k].label)}</dt><dd>${e(answerLabel(p,k))}</dd></div>`).join('')}</dl></details><div class="ex-secondary-actions">${button('Learning plan','page:plan')}${button('Export my report','export','button secondary')}${button('Print / save PDF','print','text-button')}</div>`;
}
function aiPage(report,focus){
 const r=roleById(focus)||roleById(report.ranking[0].id);
 return heading('YOUR AI RELATIONSHIP','Use assistance while keeping agency.','Usage time and reliance describe habits, not competence or replacement risk.')+`<p class="ex-local-notice">${T('This report itself used no AI inference or online prediction.')}</p><div class="chip-row">${report.profile.aiPurposes.map(v=>`<span>${e(answerLabel({...report.profile,aiPurposes:[v]},'aiPurposes'))}</span>`).join('')}</div><div class="ex-two-grid">${report.ai.map(advice).join('')}</div><section class="ex-feature"><h2>${X(r.title)}</h2><div class="ex-two-grid"><article><h3>${T('How AI could help')}</h3><p>${X(r.ai)}</p></article><article><h3>${T('What stays with you')}</h3><p>${X(r.human)}</p></article></div></section>`;
}
function careerCard(rank,p,selected,index){const r=roleById(rank.id);return `<article class="ex-role-card ${selected===r.id?'selected':''}"><div class="ex-role-top"><span class="kicker">${index<2?T(index===0?'Suggested starting direction':'Alternative to explore'):'#'+(index+1)}</span><span class="ex-score" title="${T('Rank score (editorial points)')}">${rank.score}<small>${T('Rank score (editorial points)')}</small></span></div><h2>${X(r.title)}</h2>${reasonList(rank,p)}<div class="chip-row">${r.skills.map(s=>`<span>${X(s)}</span>`).join('')}</div><details class="ex-detail"><summary>${T('Entry pathway to check')}</summary><p>${X(r.entry)}</p><h3>${T('A small project to try')}</h3><p>${X(r.project)}</p><h3>${T('How AI could help')}</h3><p>${X(r.ai)}</p><h3>${T('What stays with you')}</h3><p>${X(r.human)}</p><div class="chip-row">${r.sdgs.map(id=>`<span>SDG ${id} · ${X(goalById(id).title)}</span>`).join('')}</div></details>${button(selected===r.id?'Selected focus':'Use this for my plan',`focus:${r.id}`,selected===r.id?'button selected-button':'button secondary')}</article>`;}
function careers(report,state){return heading('CAREER PATHS','Compare A and B','These points order exploration cards. They are not fit percentages, ability scores or job-market forecasts.')+`<p>${T('A new direction can be selected from any of the 24 cards below.')}</p><div class="ex-two-grid">${report.ranking.slice(0,state.allCareers?24:4).map((r,i)=>careerCard(r,report.profile,state.focus,i)).join('')}</div><div class="ex-secondary-actions">${button(state.allCareers?'Show the leading four':'Show all 24 directions','toggle-careers','button secondary')}${button('Learning plan','page:plan')}</div>`;}
function planPage(report,focus){
 const plan=buildPlan(report.profile,focus),role=roleById(focus),actions=[['Make a baseline','Study one core skill and attempt a tiny task without AI. Keep the first attempt to compare later.','A short baseline and one question.'],['Build a bounded prototype','Choose a small part of the project below and finish one visible artifact.','One working draft or prototype.'],['Check and revise','Test three cases, log mistakes and revise one part. Compare manual and AI-assisted work only if you choose to use AI.','A three-case test log and one revision.'],['Present and decide','Show a willing peer your artifact, explain its limitations and decide whether to continue, adapt or try another direction.','A one-page portfolio note and next decision.']];
 return heading('YOUR LEARNING RHYTHM','Build evidence in four weeks.','This is a small starting commitment, not an assumption that you must use every available hour. Reduce it if needed.')+`<div class="plan-summary"><div><span>${T('Your current focus')}</span><h2>${X(role.title)}</h2><p>${X(role.project)}</p></div><div class="time-token"><strong>${T('{hours} h',{hours:plan.weeklyHours})}</strong><span>${T('Suggested weekly starting hours')}</span></div></div><div class="ex-time-split">${[['Foundations','foundation'],['Project work','project'],['Review','review']].map(([s,k])=>`<div><b>${T('{hours} h',{hours:plan.split[k]})}</b><span>${T(s)}</span></div>`).join('')}</div><div class="week-list">${plan.weeks.map(w=>{const a=actions[w.week-1];return `<article class="plan-mini"><span class="kicker">${T('Week {week}',{week:w.week})} · ${T('{hours} h',{hours:w.hours})}</span><h2>${T(a[0])}</h2><p>${T(a[1])}</p><strong>${T('Deliverable')}</strong><p>${T(a[2])}</p></article>`;}).join('')}</div><h2>${T('Your learning rhythm')}</h2><div class="ex-two-grid">${report.learning.map(advice).join('')}</div>`;
}
function companionCard(goal,rank){return `<button type="button" class="ex-goal-card" data-action="goal:${goal.id}" style="--goal-color:${goal.color}" aria-label="${X(goal.name)} · SDG ${goal.id}"><span class="ex-goal-number">${String(goal.id).padStart(2,'0')}</span>${avatar(goal,'card')}<span class="ex-goal-code">${goal.code}</span><strong>${X(goal.name)}</strong><span>${X(goal.title)}</span>${rank?`<small>${T('Your leading companions')} #${rank}</small>`:''}</button>`;}
export function renderGoals(state){
 const report=state.report,ranking=report?.goals||[],goal=goalById(state.goal||ranking[0]?.id||9),rank=ranking.find(r=>r.id===goal.id);
 return heading('YOUR ACTION COMPANION','17 goals. Many ways to contribute.','These original characters turn the UN goals into playful action prompts. They are not official UN mascots or an MBTI assessment.')+`<section class="ex-goal-feature" style="--goal-color:${goal.color}"><div>${avatar(goal,'large')}</div><div><span class="ex-goal-code">SDG ${goal.id} · ${report?e(report.preferenceCode)+' · ':''}${goal.code}</span><h2>${X(goal.name)}</h2><h3>${X(goal.title)}</h3><p>${X(goal.description)}</p><h3>${T('An action you can try')}</h3><p>${X(goal.action)}</p><p class="field-help">${T('Proposed connection, not measured SDG impact.')}</p><a class="text-button" href="${goal.url}" target="_blank" rel="noopener noreferrer">${T('UN goal and targets ↗')}</a></div></section>${report?`<div class="ex-method"><p>${T('Selected by interest overlap and links to your top three career directions.')}</p>${rank?`<p><b>${T('Matching interests')}:</b> ${rank.reasons.interests.map(i=>e(answerLabel({...report.profile,interests:[i]},'interests'))).join(' · ')||'—'}</p><p><b>${T('Career directions')}:</b> ${rank.reasons.careers.map(id=>X(roleById(id).title)).join(' · ')||'—'}</p>`:''}<p>${T('Your three-letter shorthand describes only the preferences you selected. It does not determine your abilities or career.')}</p><small>${T('I / E: inward / outward energy · J / P: planned / flexible · R / F: reasoning / empathy')}</small></div><h2>${T('Your leading companions')}</h2><div class="ex-top-goals">${ranking.slice(0,3).map((r,i)=>companionCard(goalById(r.id),i+1)).join('')}</div>`:''}<h2 class="section-space">${T('Explore all 17')}</h2><div class="ex-goal-grid">${catalog.goals.map(g=>companionCard(g)).join('')}</div><p class="field-help">${T('SDG goal titles follow the United Nations. Character names, career links and scoring are our editorial interpretations.')}</p>`;
}
export function renderCatalog(){
 const inventory=outputInventory();
 return heading('Local catalog · complete output vocabulary','All possible report components are written in advance.','The engine combines these finite modules for your answers. It does not invent new careers, fetch market data or call a model.')+`<div class="ex-stat-band"><div><b>24</b><span>${T('Career directions')}</span></div><div><b>17</b><span>${T('SDG companions')}</span></div><div><b>${inventory.adviceIds.length}</b><span>${T('Learning and AI modules')}</span></div></div><section class="ex-method"><h2>${T('Career rules')}</h2><p>${T('Each matching interest +4; matching university subject +6; school stream +2; each thinking preference +2; each AI purpose +1. Ties use the catalog order.')}</p><p>${T('Gender, nationality, personality and self-rated learning ability never add or remove career points.')}</p><h3>${T('SDG rules')}</h3><p>${T('Each matching interest +2; each of the top three careers linked to the goal +3. Ties use the goal number.')}</p><p>${T('No randomness, dates, live labour-market claims or online inference affect the result.')}</p><p><b>${T('Allowed questionnaire combinations')}:</b> ${possibleProfileCount().toLocaleString(language)}</p><p class="field-help">${T('This counts input combinations, not distinct careers or guaranteed future outcomes.')}</p><small>${T('Rules version')}: ${catalog.version}</small></section><p><a class="button secondary" href="./explorer-catalog.json" download="career-result-catalog.json">${T('Download the complete catalog')}</a></p><h2>${T('All career possibilities')}</h2><div class="ex-catalog-list">${catalog.careers.map(r=>`<details class="ex-detail"><summary>${X(r.title)}</summary><p>${X(r.entry)}</p><h3>${T('A small project to try')}</h3><p>${X(r.project)}</p><h3>${T('How AI could help')}</h3><p>${X(r.ai)}</p><h3>${T('What stays with you')}</h3><p>${X(r.human)}</p></details>`).join('')}</div><h2 class="section-space">${T('Learning and AI modules')}</h2><div class="ex-two-grid">${inventory.adviceIds.map(advice).join('')}</div>`;
}
export function renderReport(state){
 const r=state.report,content=state.content ?? (state.page==='overview'?overview(r):state.page==='ai'?aiPage(r,state.focus):state.page==='careers'?careers(r,state):state.page==='plan'?planPage(r,state.focus):state.page==='sdg'?renderGoals(state):renderCatalog());
 return `<main class="report-page shell ex-report"><aside class="report-sidebar"><div class="sidebar-sticky"><div class="report-person"><span class="person-avatar">${e(r.preferenceCode[0])}</span><div><span>${T('OFFLINE EXPLORATION')}</span><strong>${e(r.preferenceCode)}</strong></div></div><nav class="report-nav" aria-label="${T('Local report navigation')}">${(state.navigation||[...sections,...(state.extraSections||[])]).map((key,i)=>`<button type="button" data-action="page:${key}" class="${state.page===key?'active':''}" ${state.page===key?'aria-current="page"':''}><span>0${i+1}</span>${T(sectionLabels[key]||(state.extraLabels||{})[key])}<b>↗</b></button>`).join('')}</nav><div class="sidebar-bottom"><span>${T('Your current focus')}</span><p>${X(roleById(state.focus).title)}</p>${button('Edit your answers ↗','edit','text-button')}<small>${T('Rules version')}: ${r.version}<br>${e(r.reportId)}</small></div></div></aside><div class="report-main">${content}<div class="ex-report-foot"><p>${T('You can keep exploring; no selection locks you into a profession.')}</p>${button('Export my report','export','button secondary')}${button('Print / save PDF','print','text-button')}${button('Start over','reset','text-button')}</div></div></main>`;
}
export function renderStandalone(state){return `<main class="shell ex-standalone"><div class="back-row">${button('← Back to home','home','text-button')}</div>${state.page==='gallery'?renderGoals(state):renderCatalog()}</main>`;}
